/**
 * @module O 内容工具箱
 *
 * item.template 投影器——把 Resource Graph 中的 item.template 节点投影回
 * oblivions/gamedata/item_table.php 的 PHP 数组形态。
 *
 * 设计意图（执行案 06-P5 §4.3.2）：
 * - P5-2 改用 generatePhpFile API：文件头注入 `// AUTO-GENERATED FROM ...` 注释、
 *   模块标签与 sectionTitle 由 schema.projectionTargets 派生，不再使用硬编码文件头。
 * - 字段顺序由 schema projectionTargets.fieldOrder 决定：
 *     itm / itmk / itme / itms / itmsk / itmpara / desc / tier / stack / tags / use_effect / tool_level
 *   未列出的字段按原顺序追加。扩展区条目省略 itm/desc（由 presentation.item 投影）。
 * - 字段对齐由 alignmentStyle='space-padded' 决定——entry 级 key（含引号）补齐到该
 *   entry 内最长 key 长度，与原 item_table.php 的 `'itm'      =>` 风格对齐。
 * - 顶层 entry ID key 不对齐（不同 ID 长度差异大，对齐反而破坏可读性）。
 * - 106 个道具模板按节点数组顺序保留——vuedraggable 拖拽后写入图，投影时按图顺序输出。
 *
 * 字段映射：
 *   - 节点 id              → 顶层 key（item ID，如 'rusty_pipe'）
 *   - node.data.{field}    → entry 字段（按 fieldOrder 顺序输出）
 *
 * 边界：
 * - 节点 data 为 null/非对象时跳过该节点
 * - undefined 字段递归移除（与 php-adapter.stripUndefinedFields 对齐）
 * - 保留所有显式值（含 false / 0 / '' / null），保证 round-trip 一致性
 * - 扩展区条目（item_table.php:656+）省略 itm/desc，parse 时 undefined，serialize 仍省略
 *
 * 集成：
 * - php-adapter.serializePhpResource 路由到本投影器（当 kind='item.template' 时）
 * - BuildView 在发布前通过 serializeNodes 间接调用本投影器生成 PublishableFile
 */

import { generatePhpFile, type PhpValue } from '../../shared/serializer/php-codegen';
import type { ResourceNode } from '../../graph/types';
import type { SerializedPhpFile } from '../../adapters/php-adapter';

/** 目标文件路径（工作区相对路径） */
const ITEM_TABLE_FILE_PATH = 'oblivions/gamedata/item_table.php';

/** 作者资源 YAML 路径——用于 AUTO-GENERATED 注释 */
const ITEM_TABLE_AUTHOR_SOURCE = 'oblivions/content/items/items.yaml';

/**
 * item_table.php entry 级字段顺序——与 schema projectionTargets.fieldOrder 对齐。
 *
 * 该顺序与原 item_table.php 文件中每个 entry 的字段顺序一致，保证 round-trip 一致性。
 */
const ITEM_FIELD_ORDER = [
  'itm',
  'itmk',
  'itme',
  'itms',
  'itmsk',
  'itmpara',
  'desc',
  'tier',
  'stack',
  'tags',
  'use_effect',
  'tool_level',
];

/**
 * 把 item.template 节点投影回 item_table.php 形态。
 *
 * @param nodes item.template 节点数组（顺序保留为顶层 item_id 顺序）
 * @returns 单个 SerializedPhpFile（filePath 指向 oblivions/gamedata/item_table.php）
 */
export function projectItemTable(nodes: ResourceNode[]): SerializedPhpFile[] {
  const dict = buildItemTableDict(nodes);
  const content = generatePhpFile(dict, {
    module: 'F 物品系统',
    sectionTitle: 'Oblivions 道具表',
    autoGeneratedFrom: ITEM_TABLE_AUTHOR_SOURCE,
    fieldOrder: ITEM_FIELD_ORDER,
    alignmentStyle: 'space-padded',
  });
  return [{ filePath: ITEM_TABLE_FILE_PATH, content }];
}

/**
 * 把 ResourceNode[] 重建为 map-keyed PHP 字典形态。
 *
 * 节点 id 作为顶层 key（item ID），node.data 作为 value（含 itm/itmk/itme 等字段）。
 * stripUndefinedFields 递归移除 undefined 字段——扩展区条目 parse 时 data.itm===undefined，
 * serialize 时仍省略，保证 round-trip 一致性。
 *
 * 字段顺序由 generatePhpFile 的 fieldOrder 选项决定，不在此处重排。
 */
function buildItemTableDict(nodes: ResourceNode[]): PhpValue {
  const dict: Record<string, PhpValue> = {};
  for (const node of nodes) {
    if (node.data === null || typeof node.data !== 'object' || Array.isArray(node.data)) {
      continue;
    }
    const cleaned = stripUndefinedFields(node.data);
    dict[node.id] = cleaned as PhpValue;
  }
  return dict;
}

/**
 * 递归移除 undefined 字段——与 php-adapter.stripUndefinedFields 行为一致。
 *
 * 保留所有显式值（含 false / 0 / '' / null），仅移除 undefined。
 * 用于序列化时对齐扩展区条目省略字段的契约。
 */
function stripUndefinedFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(stripUndefinedFields);
  }
  if (value !== null && typeof value === 'object') {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue;
      result[k] = stripUndefinedFields(v);
    }
    return result;
  }
  return value;
}
